        mem[ 5782] = 24'h000FF8;  // U+9971 '饱' 行22
        mem[ 5783] = 24'h000000;  // U+9971 '饱' 行23
    end

    always @(posedge i_clk) begin
        o_row_bits <= mem[i_addr];
    end

endmodule
